<?php declare(strict_types=1); namespace Annam; $title='Checkout'; ?>
<section class="wrap php-store-section"><div class="page-intro"><p class="section-kicker">1 · Delivery details</p><h1>Good food, delivered to you.</h1></div><p>Meals require an approved delivery area. Snacks outside Chennai use courier delivery; courier charges are payable separately after dispatch.</p><div class="checkout-layout"><form method="post" class="checkout-card checkout-form"><?= csrf() ?><div class="checkout-fields"><?php foreach(['name'=>'Full name','phone'=>'Mobile number','email'=>'Email (optional)','line1'=>'Door number & street','line2'=>'Apartment / locality (optional)','landmark'=>'Landmark (optional)','city'=>'City','state'=>'State / region','country'=>'Country','pincode'=>'Pincode / postal code'] as $key=>$label): ?><label class="checkout-field"><span><?= e($label) ?></span><input name="<?= e($key) ?>" value="<?= e($_POST[$key]??(['country'=>'India','state'=>'Tamil Nadu'][$key]??'')) ?>" <?= in_array($key,['email','line2','landmark'])?'':'required' ?> <?= $key==='email'?'type="email"':($key==='phone'?'type="tel"':'') ?> maxlength="<?= $key==='pincode'?20:($key==='phone'?20:200) ?>"></label><?php endforeach; ?>
<label class="checkout-field"><span>Delivery area</span><select name="zone_id"><option value="">Select automatically from pincode</option><?php foreach($areas as $area): ?><option value="<?= e($area['id']) ?>"><?= e($area['pincode'].' · '.$area['area_name']) ?></option><?php endforeach; ?></select></label><label class="checkout-field"><span>Payment</span><select name="payment_method" required><?php foreach($choices as $key=>$label): ?><option value="<?= e($key) ?>"><?= e($label) ?></option><?php endforeach; ?></select></label></div><p><?= !empty($store->config['features']['checkout_test_mode'])?'Temporary TEST checkout is enabled.':(!$choices?'Online payment is currently unavailable. Please try again later.':'Pay online to confirm your order.') ?></p><p>Items subtotal: <strong><?= Money::display($quote['subtotal']) ?></strong>. Delivery and applicable taxes appear on the next step.</p><button class="btn btn-primary" <?= !$choices?'disabled':'' ?>>Review order →</button></form><aside class="summary"><h2>Your order</h2><?php foreach($quote['lines'] as $line):?><p class="php-total"><span><?= e($line['quantity'].' × '.$line['item']['name']) ?></span><strong><?= Money::display($line['amount']) ?></strong></p><?php endforeach;?><p class="php-total"><strong>Items subtotal</strong><strong><?= Money::display($quote['subtotal']) ?></strong></p><p>Delivery and any applicable taxes are confirmed when you review your order.</p><a href="/cart/">Edit your cart →</a></aside></div></section>
